      SUBROUTINE VARY1(IVAR)C---- DECLARE PARAMETER AS VARIABLEC-------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDWRDS.CIN'C-------------------------------------------------------------------      CHARACTER*15    KNAME, KPARA      INTEGER         TEXT      EXTERNAL        IDATA, TEXTC-------------------------------------------------------------------CC---- COMMA?C      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800      ENDIFCC---- PARAMETER KEYWORDC      CALL RDWORD(KNAME,LNAME)      IF (KNAME .EQ. 'ALL') GO TO 300      IF (KNAME .NE. 'NAME') GO TO 50      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .NE. EQUAL) THEN        CALL RDFAIL        WRITE (IECHO,905)        GO TO 800      ENDIFCC---- PARAMETER NAMEC      CALL RDNEXT      IF (ENDFIL) GO TO 800      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 800      ENDIFC   50 IELEM = 0      IPARM = 0      IHIGH = 0      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. '[') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800        CALL RDWORD(KPARA,LPARA)        IF (LPARA .EQ. 0) THEN          CALL RDFAIL          WRITE (IECHO,930)          GO TO 800        ENDIF        CALL RDNEXT        IF (ENDFIL) GO TO 800        CALL RDTEST(']',ERROR)        IF (ERROR) GO TO 800        IF (TEXT(1) .LT. 0) GO TO 600C        DO 100 NUM = 1, NEL        IF (LABEL(NUM) .NE. KNAME) GO TO 100        II = ISTOR(NUM)        IF (II .LT. IHIGH) GO TO 100        IHIGH = MAX0(II,IHIGH)        IF (DATA(II) .LT. 0) GO TO 100        IELEM = IELEM + 1        NTYPE = IDATA(II)        CALL RDPARS(KPARA,LPARA,IEP)        IF (NTYPE .EQ. 14) THEN          NROW = IFIX(DATA(II+7))          IF (J1 .NE. NROW) IEP = 0        ENDIF        IF (IEP .EQ. 0) GO TO 100        CALL SKETCH(NUM)        IF (NTYPE .NE. 16) THEN          IDIF = IPTOJ(IEP)        ELSE          IDIF = 2        ENDIF        IF (IDIF .EQ. 0) GO TO 100        IPARM = IPARM + 1        IADR = II + IDIF        IF (TIE(IADR) .LT. 99) THEN          TIE(IADR) = IVAR        ELSE          CALL RDWARN          WRITE (IECHO,950)          GO TO 800        ENDIF  100   CONTINUEC        IF (IELEM .EQ. 0) THEN          CALL RDFAIL          WRITE (IECHO,920) KNAME(1:LNAME)          GO TO 800        ENDIF        IF (IPARM .EQ. 0) THEN          CALL RDFAIL          WRITE (IECHO,940) KNAME(1:LNAME), KPARA(1:LPARA)          GO TO 800        ENDIF      ELSE        IF (TEXT(1) .LT. 0) GO TO 600        DO 200 NUM = 1, NEL        IF (LABEL(NUM) .NE. KNAME) GO TO 200        II = ISTOR(NUM)        IF (II .LT. IHIGH) GO TO 200        IHIGH = MAX0(II,IHIGH)        IELEM = IELEM + 1        IF (TIE(II+1) .LT. 99) THEN          TIE(II+1) = IVAR        ELSE          CALL RDWARN          WRITE (IECHO,950)          GO TO 800        ENDIF  200   CONTINUE        IF (IELEM .EQ. 0) THEN          CALL RDFAIL          WRITE (IECHO,920) KNAME(1:LNAME)          GO TO 800        ENDIF      ENDIF      GO TO 600C  300 ILAST = ISTOR(NEL+1) - 1      DO 320 I = 1, ILAST      ITIE = TIE(I)      IF (ITIE .NE. 99 .AND. ITIE .NE. 100) ITIE = 0      TIE(I) = ITIE  320 CONTINUE  600 CONTINUE      GO TO 900CC---- ERROR EXITC  800 ERROR = .TRUE.  900 RETURNC------------------------------------------------------------------  905 FORMAT (' *** ERROR *** EQUAL EXPECTED'/' ')  910 FORMAT (' *** ERROR *** PARAMETER NAME EXPECTED'/' ')  920 FORMAT (' *** ERROR *** UNKNOWN BEAM ELEMENT "',A,'"'/' ')  930 FORMAT (' *** ERROR *** PARAMETER KEYWORD EXPECTED'/' ')  940 FORMAT (' *** ERROR *** UNKNOWN ELEMENT PARAMETER "',     +        A,' ',A,' "'/' ')  950 FORMAT (' *** ERROR *** DEPENDENT PARAMETER CANNOT BE VARIED'/' ')  960 FORMAT (' ** WARNING ** "STEP" MISSING ---',     +        ' THIS MAY CAUSE TROUBLE IN MATCHING'/' ')  970 FORMAT (' ** WARNING ** THIS PARAMETER IS ALREADY VARIABLE',     +        ' --- NEW DATA USED'/' ')  980 FORMAT (' *** ERROR *** THIS VERSION OF "MAD" ACCEPTS ONLY ',     +        I5,' VARIABLE PARAMETERS --- "VARY" IGNORED'/' ')C-------------------------------------------------------------------      END